pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 fallbackCount, uint256 sendValue) public {
        // Constrain sendValue to avoid out-of-gas
        vm.assume(sendValue <= address(this).balance);
        // Record count before any calls
        uint256 countBefore = c.depositsCount();

        // Make fallback calls via plain transfer (or call)
        for (uint256 i = 0; i < fallbackCount; i++) {
            (bool ok,) = address(c).call{value: 1 wei}("");
            require(ok);
        }

        // Verify count equals number of fallback calls (reference invariant)
        uint256 countAfterFallback = c.depositsCount();
        assertTrue(countAfterFallback == fallbackCount + countBefore, "fallback count mismatch");

        // Now make one sendMoney call
        uint256 sendVal = bound(sendValue, 0, address(c).balance);
        (bool success,) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, address(this), sendVal));
        require(success);

        // After sendMoney, depositsCount must be unchanged from after fallback
        uint256 countAfterSend = c.depositsCount();
        assertTrue(countAfterSend == countAfterFallback, "sendMoney changed depositsCount");
    }
}

